import { execSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';

const raw = execSync('npx supabase status -o json', { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
const status = JSON.parse(raw.slice(raw.indexOf('{')));
const lines = [
  '# Generated by scripts/write-local-env.mjs from `supabase status` (local development only).',
  '# "/sb" is proxied by the Vite dev/preview server to the local API, so the same value works on',
  '# desktop and on a phone through the Cloudflare tunnel. A cloud project uses its https URL here.',
  'VITE_SUPABASE_URL=/sb',
  `VITE_SUPABASE_ANON_KEY=${status.ANON_KEY}`,
  `SUPABASE_URL=${status.API_URL}`,
  `SUPABASE_SERVICE_ROLE_KEY=${status.SERVICE_ROLE_KEY}`,
  '',
];
writeFileSync(new URL('../.env.local', import.meta.url), lines.join('\n'));
console.log('Wrote .env.local for', status.API_URL);
